    "content": "12/03|\u10D0\u10DB \u10D3\u10E6\u10D4\u10E1, 1930 \u10EC\u10DA\u10D8\u10E1 12 \u10DB\u10D0\u10E0\u10E2\u10E1, \u10DB\u10D0\u10F0\u10D0\u10D7\u10DB\u10D0 \u10D2\u10D0\u10DC\u10D3\u10D8\u10DB \u10DB\u10D0\u10E0\u10D8\u10DA\u10D8\u10E1 \u10DB\u10D0\u10E0\u10E8\u10D8\u10E1 \u10D3\u10D0\u10EC\u10E7\u10D4\u10D1\u10D8\u10D7 \u10D1\u10E0\u10D8\u10E2\u10D0\u10DC\u10D4\u10D7\u10D8\u10E1 \u10DB\u10DD\u10DC\u10DD\u10DE\u10DD\u10DA\u10D8\u10D0\u10E1 \u10D3\u10D0\u10E3\u10DE\u10D8\u10E0\u10D8\u10E1\u10DE\u10D8\u10E0\u10D3\u10D0.",
