    "content": "06/01|\u10D0\u10DB \u10D3\u10E6\u10D4\u10E1, 1838 \u10EC\u10DA\u10D8\u10E1 6 \u10D8\u10D0\u10DC\u10D5\u10D0\u10E0\u10E1, \u10E1\u10D0\u10DB\u10E3\u10D4\u10DA \u10DB\u10DD\u10E0\u10D6\u10D4\u10DB \u10D5\u10D0\u10E8\u10D8\u10DC\u10D2\u10E2\u10DD\u10DC\u10E8\u10D8 \u10E2\u10D4\u10DA\u10D4\u10D2\u10E0\u10D0\u10E4\u10D8\u10E1 \u10E1\u10D8\u10E1\u10E2\u10D4\u10DB\u10D8\u10E1 \u10E1\u10D0\u10EF\u10D0\u10E0\u10DD \u10D3\u10D4\u10DB\u10DD\u10DC\u10E1\u10E2\u10E0\u10D0\u10EA\u10D8\u10D0 \u10E9\u10D0\u10D0\u10E2\u10D0\u10E0\u10D0.",
