    "content": "\u201E\u10D0\u10E0 \u10D2\u10D0\u10D6\u10DD\u10DB\u10DD \u10E8\u10D4\u10DC\u10D8 \u10EA\u10EE\u10DD\u10D5\u10E0\u10D4\u10D1\u10D0 \u10DB\u10EE\u10DD\u10DA\u10DD\u10D3 \u10D8\u10DB\u10D8\u10D7, \u10E0\u10D0\u10EA \u10DB\u10D8\u10D0\u10E6\u10EC\u10D8\u10D4; \u10D2\u10D0\u10D6\u10DD\u10DB\u10D4 \u10D8\u10DB\u10D8\u10D7\u10D0\u10EA, \u10D5\u10D8\u10DC\u10EA \u10D2\u10D0\u10EE\u10D3\u10D8.\u201C",
