    "content": "06/01|\u10D0\u10DB \u10D3\u10E6\u10D4\u10E1, 1912 \u10EC\u10DA\u10D8\u10E1 6 \u10D8\u10D0\u10DC\u10D5\u10D0\u10E0\u10E1, \u10DC\u10D8\u10E3-\u10DB\u10D4\u10E5\u10E1\u10D8\u10D9\u10DD \u10D0\u10E8\u10E8-\u10D8\u10E1 47-\u10D4 \u10E8\u10E2\u10D0\u10E2\u10D8 \u10D2\u10D0\u10EE\u10D3\u10D0.",
