    "content": "\u10DB\u10D4\u10DD\u10E0\u10D0\u10D3\u10D8 \u10DB\u10D0\u10DC\u10E5\u10D0\u10DC\u10D8\u10E1 \u10E7\u10D8\u10D3\u10D5\u10D8\u10E1\u10D0\u10E1 OBD \u10D3\u10D8\u10D0\u10D2\u10DC\u10DD\u10E1\u10E2\u10D8\u10D9\u10D0 \u10E9\u10D0\u10D0\u10E2\u10D0\u10E0\u10D4.",
