    "content": "11/03|\u10D0\u10DB \u10D3\u10E6\u10D4\u10E1, 1938 \u10EC\u10DA\u10D8\u10E1 11 \u10DB\u10D0\u10E0\u10E2\u10E1, \u10D0\u10D5\u10E1\u10E2\u10E0\u10D8\u10D8\u10E1 \u10D0\u10DC\u10E8\u10DA\u10E3\u10E1\u10D8\u10E1 \u10DE\u10E0\u10DD\u10EA\u10D4\u10E1\u10D8 \u10D3\u10D0\u10D8\u10EC\u10E7\u10DD.",
