    "category": "\u10E4\u10E1\u10D8\u10E5\u10DD\u10DA\u10DD\u10D2\u10D8\u10D0",
    "content": "\u10D0\u10D3\u10D0\u10DB\u10D8\u10D0\u10DC\u10D4\u10D1\u10D8 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10E1\u10D0\u10D9\u10E3\u10D7\u10D0\u10E0 \u10E8\u10D4\u10EA\u10D3\u10DD\u10DB\u10D4\u10D1\u10E1 \u10E1\u10EE\u10D5\u10D4\u10D1\u10D8\u10E1 \u10E8\u10D4\u10EA\u10D3\u10DD\u10DB\u10D4\u10D1\u10D6\u10D4 \u10E3\u10E4\u10E0\u10DD \u10DB\u10D9\u10D0\u10EA\u10E0\u10D0\u10D3 \u10D0\u10E4\u10D0\u10E1\u10D4\u10D1\u10D4\u10DC, \u10E0\u10D0\u10D3\u10D2\u10D0\u10DC \u10E1\u10D0\u10D9\u10E3\u10D7\u10D0\u10E0 \u10DB\u10DD\u10E2\u10D8\u10D5\u10D4\u10D1\u10E1\u10D0 \u10D3\u10D0 \u10D2\u10D0\u10E0\u10D4\u10DB\u10DD\u10D4\u10D1\u10D4\u10D1\u10E1 \u10E3\u10D9\u10D4\u10D7 \u10D8\u10EA\u10DC\u10DD\u10D1\u10D4\u10DC.",
