    "content": "\u10EC\u10E7\u10DA\u10D8\u10E1 \u10D1\u10DD\u10D7\u10DA\u10D8 \u10DB\u10E3\u10D3\u10D0\u10DB \u10D7\u10D5\u10D0\u10DA\u10E1\u10D0\u10E9\u10D8\u10DC\u10DD \u10D0\u10D3\u10D2\u10D8\u10DA\u10D0\u10E1 \u10D2\u10D4\u10D3\u10DD\u10E1 \u2014 \u10DB\u10D4\u10E2 \u10EC\u10E7\u10D0\u10DA\u10E1 \u10D3\u10D0\u10DA\u10D4\u10D5.",
