    "content": "\u201E\u10EA\u10EE\u10DD\u10D5\u10E0\u10D4\u10D1\u10D8\u10E1 \u10EE\u10D0\u10E0\u10D8\u10E1\u10EE\u10E1 \u10EE\u10E8\u10D8\u10E0\u10D0\u10D3 \u10D2\u10D0\u10DC\u10E1\u10D0\u10D6\u10E6\u10D5\u10E0\u10D0\u10D5\u10E1 \u10D8\u10E1, \u10E0\u10D0\u10D6\u10D4 \u10D0\u10DB\u10D1\u10DD\u10D1 \u10E3\u10D0\u10E0\u10E1.\u201C",
